			writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "user_id: does not exist")
			return
		}
		userID = req.UserID
	}

	review := Review{
		ProductID: req.ProductID,
		UserID:    userID,
		Rating:    req.Rating,
		Body:      req.Body,
	}

	if review.Rating < 1 || review.Rating > 5 {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "rating must be between 1 and 5")
		return
	}

	if len(review.Body) > 500 {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "body exceeds 500 characters")
		return
	}

	s.reviews.Create(review)
	writeJSON(w, http.StatusCreated, review)
}

