	}

	p, err := parsePage(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, codeBadQuery, err.Error())
		return
	}

	reviews, info := paginate(s.reviews.ListByProduct(productID), p)
	writeList(w, reviews, info)
}

// handleCreateReview creates a new review with validation.
func handleCreateReview(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path().Segments()[1]
	productID := id
	if !strings.HasPrefix(id, "prod") {
		writeNotFound(w, "product", id)
		return
	}

	var req createReviewRequest
	if err := decodeBody(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, codeBadJSON, "request body must be valid JSON")
		return
	}

	if err := req.validate(); err != nil {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, err.Error())
		return
	}

	userID, exists := s.reviews.Get(req.UserID)
	if !exists {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "user_id: unknown user")
		return
	}

	req.UserID = userID

	rv := req.Review
	st.Create(rv)

	writeJSON(w, http.StatusCreated, rv)
}

